const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',light:'M9 18h6 M10 21h4 M8 14a6 6 0 1 1 8 0l-1 2H9z',fan:'M12 12c-9-1-9-10-3-10 5 0 4 7 3 10z M12 12c5-7 13-3 10 2-3 4-8 0-10-2z M12 12c4 8-3 14-6 9-3-5 4-8 6-9z',energy:'M13 2L4 14h7l-1 8 10-13h-8z',leaf:'M20 3C8 1 1 9 6 16s16 2 14-13z M5 21l10-12',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12z',sun:'M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',film:'M3 5h18v14H3z M7 5v14 M17 5v14 M3 9h4 M3 15h4 M17 9h4 M17 15h4',away:'M9 4H3v16h6 M10 12h12 M17 7l5 5-5 5',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',plus:'M12 5v14 M5 12h14',power:'M12 2v10 M7 5a8 8 0 1 0 10 0',tablet:'M5 2h14v20H5z M11 18h2',plug:'M8 2v5 M16 2v5 M5 7h14v5a7 7 0 0 1-14 0z M12 19v3',climate:'M10 14V4a2 2 0 0 1 4 0v10a4 4 0 1 1-4 0 M12 9v8',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',check:'M5 12l4 4L19 6',info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.grid}"/></svg>`;
const initial=[{id:1,name:'Pendant lights',room:'Living room',type:'light',on:true,value:75,temp:3200,color:'#edc780',watts:36},{id:2,name:'Ceiling fan',room:'Living room',type:'fan',on:true,value:45,watts:70},{id:3,name:'Ambient LED strip',room:'Living room',type:'light',on:true,value:60,temp:4000,color:'#a1c985',watts:24},{id:4,name:'Smart thermostat',room:'Living room',type:'climate',on:true,value:23,watts:1200},{id:5,name:'Bedside lamp',room:'Bedroom',type:'light',on:false,value:40,temp:2700,color:'#edc780',watts:12},{id:6,name:'Bedroom fan',room:'Bedroom',type:'fan',on:false,value:30,watts:65},{id:7,name:'Counter lights',room:'Kitchen',type:'light',on:true,value:85,temp:4500,color:'#fff2c5',watts:30},{id:8,name:'Coffee station',room:'Kitchen',type:'plug',on:false,value:100,watts:850},{id:9,name:'Wall tablet',room:'Office',type:'tablet',on:true,value:80,watts:15},{id:10,name:'Desk lamp',room:'Office',type:'light',on:false,value:65,temp:4200,color:'#fff2c5',watts:15}];
let devices=structuredClone(initial),view='Overview',room='All rooms',scene='',prefs={control:'slider',compact:false},events=['Demo home loaded','Fosslink hub connected'],period='Today';
try{prefs={...prefs,...JSON.parse(localStorage.getItem('fosslink-preferences')||'{}')}}catch{}
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function watts(d){return d.on?d.watts*(d.type==='climate'?Math.max(.2,Math.min(.95,(30-d.value)*.07+.15)):d.type==='plug'?1:d.value/100):0}function total(){return devices.reduce((s,d)=>s+watts(d),0)}function full(){return devices.reduce((s,d)=>s+d.watts,0)}function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3200)}
function chart(big=false){return `<div class="chart ${big?'big-chart':''}" role="img" aria-label="Illustrative energy use by hour">${[27,20,16,24,33,50,72,57,85,68,43,30].map((v,i)=>`<div class="bar" style="height:${Math.min(100,Math.max(4,v*(.55+total()/3000)))}%" title="${i*2}:00 · illustrative usage"></div>`).join('')}</div><div class="axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span></div>`}
function deviceState(d){return !d.on?'Off':d.type==='climate'?`Cooling · ${d.value} °C`:d.type==='plug'?'On':`${d.value}%`}
function range(d,key,label,min,max,unit){const pct=(d[key]-min)/(max-min)*100;return `<div class="tile-control"><div class="slider-label"><span>${label}</span><output id="out-${d.id}-${key}">${d[key]}${unit}</output></div>${prefs.control==='slider'?`<input class="tile-slider" aria-label="${esc(d.name)} ${label}" type="range" min="${min}" max="${max}" step="${key==='temp'?100:1}" value="${d[key]}" style="--position:${pct}%" data-id="${d.id}" data-key="${key}" data-unit="${unit}">`:`<div class="number-control"><button aria-label="Decrease ${esc(d.name)} ${label}" data-step="-${key==='temp'?100:1}" data-id="${d.id}" data-key="${key}" data-min="${min}" data-max="${max}">−</button><span>${d[key]}${unit}</span><button aria-label="Increase ${esc(d.name)} ${label}" data-step="${key==='temp'?100:1}" data-id="${d.id}" data-key="${key}" data-min="${min}" data-max="${max}">+</button></div>`}</div>`}
function card(d){return `<article class="device type-${d.type} ${d.on?'':'off'}" data-card="${d.id}" style="--light-color:${d.color||'#c6b0ea'}"><div class="tile-head"><button class="device-icon" data-toggle="${d.id}" role="switch" aria-label="${esc(d.name)} power" aria-checked="${d.on}">${icon(d.type)}</button><button class="device-info" data-detail="${d.id}" aria-label="Open ${esc(d.name)} controls"><b>${esc(d.name)}</b><span>${deviceState(d)}</span></button><button class="switch" role="switch" aria-label="${esc(d.name)} on or off" aria-checked="${d.on}" data-toggle="${d.id}"></button></div>${d.type==='light'?range(d,'value','Brightness',0,100,'%'):d.type==='fan'?range(d,'value','Fan speed',0,100,'%'):d.type==='climate'?range(d,'value','Temperature',16,30,' °C'):d.type==='tablet'?range(d,'value','Display brightness',0,100,'%'):''}<div class="device-footer"><span id="watts-${d.id}">${Math.round(watts(d))} W</span><div>${d.type==='light'?`<button class="color-shortcut" data-detail="${d.id}" data-mode="color" aria-label="Open ${esc(d.name)} color picker"><i style="background:${d.color}"></i> Color</button>`:''}<button data-timer="${d.id}">${icon('clock')} ${d.until?'Timer set':'Timer'}</button></div></div></article>`}
function roomCards(){return `<div class="room-groups">${['Living room','Bedroom','Kitchen','Office'].filter(r=>room==='All rooms'||room===r).map(r=>`<section class="room-group"><h3>${icon('home')}${r}<span>${devices.filter(d=>d.room===r).length} devices</span></h3><div class="devices">${devices.filter(d=>d.room===r).map(card).join('')||'<div class="empty">No devices in this room yet.</div>'}</div></section>`).join('')}</div>`}
let detailId=null,detailMode='brightness';
function hexHSV(hex){const rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255),max=Math.max(...rgb),min=Math.min(...rgb),diff=max-min;let h=0;if(diff){const i=rgb.indexOf(max);h=(i===0?(rgb[1]-rgb[2])/diff:i===1?(rgb[2]-rgb[0])/diff+2:(rgb[0]-rgb[1])/diff+4)*60}return{h:(h+360)%360,s:max?diff/max:0,v:max}}
function hsvHex(h,s,v=1){const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;const rgb=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+rgb.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join('')}
function detailBody(d){const isTemp=detailMode==='temperature';const key=isTemp?'temp':'value',min=isTemp?2200:d.type==='climate'?16:0,max=isTemp?6500:d.type==='climate'?30:100,unit=isTemp?' K':d.type==='climate'?' °C':'%',label=isTemp?'Color temperature':d.type==='fan'?'Fan speed':d.type==='climate'?'Target temperature':d.type==='tablet'?'Display brightness':'Brightness';const hsv=hexHSV(d.color||'#ffffff');const left=50+Math.sin(hsv.h*Math.PI/180)*hsv.s*49,top=50-Math.cos(hsv.h*Math.PI/180)*hsv.s*49;return `<div class="detail-header"><button data-close aria-label="Close device controls">×</button><h2>${esc(d.name)}</h2><span>${esc(d.room)}</span></div><div class="detail-status"><strong>${deviceState(d)}</strong><span>Demo device · changes apply instantly</span></div><div class="picker-area">${detailMode==='color'&&d.type==='light'?`<div class="color-wheel" role="group" aria-label="Light color wheel" data-wheel="${d.id}" tabindex="0" aria-describedby="wheel-help"><i class="wheel-marker" style="left:${left}%;top:${top}%"></i></div><p id="wheel-help" class="wheel-help">Drag to choose · arrow keys adjust hue and saturation</p><div class="hex-control"><label for="detail-color">Color</label><input id="detail-color" type="color" value="${d.color}" aria-label="Choose exact light color" data-detail-color="${d.id}"><output id="hex-output">${d.color.toUpperCase()}</output></div>`:d.type==='plug'?`<div class="plug-status">${icon('plug')}<p>Smart outlet</p><strong>${Math.round(watts(d))} W</strong></div>`:`<div class="vertical-control ${isTemp?'temperature':''}" style="--position:${(d[key]-min)/(max-min)*100}%;--light-color:${d.color||'#c8b7ed'}"><div class="vertical-fill"></div><span class="vertical-handle"></span><input aria-label="${label}" class="vertical-slider" type="range" min="${min}" max="${max}" step="${isTemp?100:1}" value="${d[key]}" data-detail-key="${key}" data-id="${d.id}" data-min="${min}" data-max="${max}"></div><div class="detail-value"><span>${label}</span><output id="detail-output">${d[key]}${unit}</output></div>`}</div><div class="detail-modes"><button data-detail-power="${d.id}" class="power-button ${d.on?'is-on':''}" aria-label="${d.on?'Turn off':'Turn on'} ${esc(d.name)}">${icon('power')}</button>${d.type==='light'?`<span class="mode-separator"></span><button data-detail-mode="brightness" class="${detailMode==='brightness'?'selected':''}" aria-label="Brightness" aria-pressed="${detailMode==='brightness'}">${icon('sun')}</button><button data-detail-mode="color" class="${detailMode==='color'?'selected':''}" aria-label="Color" aria-pressed="${detailMode==='color'}"><i class="color-mode-icon"></i></button><button data-detail-mode="temperature" class="${detailMode==='temperature'?'selected':''}" aria-label="Temperature" aria-pressed="${detailMode==='temperature'}"><i class="temp-mode-icon"></i></button>`:''}</div>`}
function showDetail(id,mode='brightness'){detailId=Number(id);detailMode=mode;const d=devices.find(d=>d.id===detailId);modal.className=`device-dialog type-${d.type}`;modal.innerHTML=detailBody(d);if(!modal.open)modal.showModal()}
function syncDetail(d){const power=modal.querySelector('[data-detail-power]');if(power){power.classList.toggle('is-on',d.on);power.setAttribute('aria-label',(d.on?'Turn off ':'Turn on ')+d.name)}const status=modal.querySelector('.detail-status strong');if(status)status.textContent=deviceState(d);const hex=modal.querySelector('#hex-output');if(hex)hex.textContent=d.color.toUpperCase();const color=modal.querySelector('#detail-color');if(color)color.value=d.color;const marker=modal.querySelector('.wheel-marker');if(marker){const hsv=hexHSV(d.color);marker.style.left=(50+Math.sin(hsv.h*Math.PI/180)*hsv.s*49)+'%';marker.style.top=(50-Math.cos(hsv.h*Math.PI/180)*hsv.s*49)+'%'}render()}
app.addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b)showDetail(b.dataset.detail,b.dataset.mode||'brightness')});
modal.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.detailMode){detailMode=b.dataset.detailMode;modal.innerHTML=detailBody(devices.find(d=>d.id===detailId));modal.querySelector(`[data-detail-mode="${detailMode}"]`)?.focus()}if(b.dataset.detailPower){const d=devices.find(d=>d.id===detailId);d.on=!d.on;scene='';log(`${d.name} turned ${d.on?'on':'off'}`);modal.innerHTML=detailBody(d);render();modal.querySelector('[data-detail-power]')?.focus()}});
modal.addEventListener('input',e=>{if(e.target.id==='name')e.target.setCustomValidity('');const d=devices.find(d=>d.id===detailId);if(!d)return;if(e.target.dataset.detailKey){const key=e.target.dataset.detailKey;d[key]=Number(e.target.value);if(key==='value'&&d.type!=='climate')d.on=d.value>0;const container=e.target.closest('.vertical-control');container.style.setProperty('--position',((d[key]-Number(e.target.min))/(Number(e.target.max)-Number(e.target.min))*100)+'%');modal.querySelector('#detail-output').textContent=d[key]+(key==='temp'?' K':d.type==='climate'?' °C':'%');scene='';syncDetail(d)}if(e.target.dataset.detailColor){d.color=e.target.value;scene='';syncDetail(d)}});
function pickWheel(e,wheel){const rect=wheel.getBoundingClientRect(),x=(e.clientX-rect.left-rect.width/2)/(rect.width/2),y=(e.clientY-rect.top-rect.height/2)/(rect.height/2);const h=(Math.atan2(x,-y)*180/Math.PI+360)%360,s=Math.min(1,Math.sqrt(x*x+y*y));const d=devices.find(d=>d.id===Number(wheel.dataset.wheel));d.color=hsvHex(h,s);scene='';syncDetail(d)}
modal.addEventListener('pointerdown',e=>{const wheel=e.target.closest('[data-wheel]');if(!wheel)return;e.preventDefault();wheel.focus();wheel.setPointerCapture(e.pointerId);pickWheel(e,wheel)});
modal.addEventListener('pointermove',e=>{const wheel=e.target.closest('[data-wheel]');if(wheel&&wheel.hasPointerCapture(e.pointerId))pickWheel(e,wheel)});
modal.addEventListener('pointerup',e=>{const wheel=e.target.closest('[data-wheel]');if(wheel&&wheel.hasPointerCapture(e.pointerId))wheel.releasePointerCapture(e.pointerId)});
modal.addEventListener('keydown',e=>{const wheel=e.target.closest('[data-wheel]');if(!wheel||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const d=devices.find(d=>d.id===Number(wheel.dataset.wheel)),hsv=hexHSV(d.color);if(e.key==='ArrowLeft')hsv.h=(hsv.h+355)%360;if(e.key==='ArrowRight')hsv.h=(hsv.h+5)%360;if(e.key==='ArrowUp')hsv.s=Math.min(1,hsv.s+.05);if(e.key==='ArrowDown')hsv.s=Math.max(0,hsv.s-.05);d.color=hsvHex(hsv.h,hsv.s);syncDetail(d)});
modal.addEventListener('close',()=>{detailId=null;modal.className=''});

function scenes(){return `<div class="section-heading"><h2>A little mood, one tap away</h2><span>Scenes</span></div><div class="scene-row">${[['sun','Good morning','A brighter start'],['film','Movie time','Settle into the evening'],['moon','Good night','Let your home rest'],['away','Away','Save while you’re out']].map(([i,n,s])=>`<button class="scene ${scene===n?'selected':''}" data-scene="${n}" aria-pressed="${scene===n}"><span class="icon">${icon(i)}</span><span><b>${n}</b><small>${s}</small></span></button>`).join('')}</div>`}
function energyRail(){return `<div class="rail-card"><div class="section-heading"><h2>Energy at a glance</h2>${icon('energy')}</div><div class="energy-total" id="daily">${(total()*8/1000).toFixed(2)} <small>kWh / 8 hours</small></div><span class="muted" style="font-size:12px">At your current device settings · illustrative pattern</span>${chart()}<div class="energy-key"><span>Estimated cost</span><b id="cost">₹${(total()*8/1000*8).toFixed(2)}</b></div></div><div class="rail-card saving">${icon('leaf')}<h3>A little less energy. A lot more care.</h3><p id="saving">Your settings use ${Math.round((1-total()/full())*100)}% less power than all devices at full output.</p></div><div class="rail-card"><h2>Around your home</h2>${events.slice(0,3).map((e,i)=>`<div class="event">${icon(i?'home':'check')}<div>${esc(e)}<small>${i?'Demo activity':'Just now'}</small></div></div>`).join('')}</div>`}
function dashboard(){return `<div class="overview"><div class="welcome"><div class="eyebrow">FOSSLINK LIVE DEMO</div><h2>A comfortable home.<br>A lighter footprint.</h2><small>Everything you need, a touch away.</small><div class="weather">${icon('sun')}</div></div><div class="stat"><div class="stat-head">${icon('plug')} Devices at work</div><strong id="active-count">${devices.filter(d=>d.on).length} <small>/ ${devices.length} devices</small></strong><p>Connected in this demo</p></div><div class="stat"><div class="stat-head">${icon('energy')} Power right now</div><strong id="power">${(total()/1000).toFixed(2)} <small>kW</small></strong><p>Updates as you adjust your home</p></div></div>${scenes()}<div class="workspace"><section><div class="section-heading"><h2>Your devices <span>(${devices.length})</span></h2><button data-master="true" style="font-size:12px;padding:6px 10px">${devices.some(d=>d.on)?'Turn all off':'Turn all on'}</button></div><div class="room-tabs" aria-label="Filter by room">${['All rooms','Living room','Bedroom','Kitchen','Office'].map(r=>`<button data-room="${r}" class="${room===r?'active':''}" aria-pressed="${room===r}">${r}</button>`).join('')}</div>${roomCards()}</section><section class="rail" aria-label="Energy and activity">${energyRail()}</section></div>`}
function energyView(){let factor=period==='Today'?1:period==='Week'?7:30;return `<div class="room-tabs">${['Today','Week','Month'].map(p=>`<button data-period="${p}" class="${period===p?'active':''}">${p}</button>`).join('')}</div><div class="overview"><div class="stat"><div class="stat-head">Projected consumption</div><strong>${(total()*8*factor/1000).toFixed(2)} <small>kWh</small></strong><p>8 operating hours per day</p></div><div class="stat"><div class="stat-head">Projected cost</div><strong>₹${(total()*8*factor/1000*8).toFixed(0)}</strong><p>Illustrative tariff: ₹8 / kWh</p></div><div class="stat"><div class="stat-head">Potential savings</div><strong>₹${((full()-total())*8*factor/1000*8).toFixed(0)}</strong><p>Versus all devices at full power</p></div></div><div class="workspace"><div class="rail-card"><h2>Your daily energy rhythm</h2><p class="footnote">Illustrative hourly pattern, scaled to current power. This is not meter history.</p>${chart(true)}<h2 style="margin-top:35px">Where your power goes</h2>${devices.map(d=>`<div class="energy-key"><span>${esc(d.name)}</span><b>${Math.round(watts(d))} W</b></div>`).join('')}</div><div>${energyRail()}</div></div>`}
function systemView(){return `<div class="welcome" style="margin-bottom:24px"><div class="eyebrow">MEET FOSSLINK</div><h2 style="max-width:none">One home. One thoughtful system.</h2><p style="margin-bottom:0;color:#d7e6dc">Lighting, comfort, control and energy awareness, brought together.</p></div><div class="view-grid">${[['home','The idea','Give every room an intuitive control surface. Adjust individual devices or coordinate your home with one scene.'],['grid','The system','A home hub connects compatible devices to a responsive dashboard on a phone, tablet, laptop or wall display.'],['leaf','The impact','See how device choices affect power use. Explore consumption and savings before deciding what to automate.']].map(([i,n,p])=>`<article class="rail-card large">${icon(i)}<h2 style="margin:18px 0">${n}</h2><p>${p}</p></article>`).join('')}</div><div class="rail-card large"><h2>From a tap to a more comfortable room</h2><p style="margin-top:20px">1. Choose a device or scene → 2. Adjust your preferences → 3. See device state and energy estimates update.</p><p>This browser demo simulates a connected home. Real device discovery, hub integration, secure remote access and measured energy data require a connected hub and compatible hardware.</p><button class="primary" data-nav="Overview">Explore the demo</button></div>`}
function render(){app.innerHTML=`<div class="shell ${prefs.compact?'compact':''}"><aside><a class="brand" href="https://www.fosslink.in/" target="_blank" rel="noopener" aria-label="Fosslink main website"><img src="favicon.svg" alt="" width="35" height="35">Fosslink</a><div class="home-switch">${icon('home')}<div><strong style="font-size:14px">Fosslink demo home</strong><small>Interactive demo</small></div></div><p class="nav-label">YOUR SPACE</p><nav>${[['Overview','grid'],['Energy','energy'],['The system','home']].map(([n,i])=>`<button data-nav="${n}" class="${view===n?'active':''}" ${view===n?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}</nav><a class="quote-link" href="https://www.fosslink.in/contact" target="_blank" rel="noopener">Request a quote <span>↗</span></a><div class="side-bottom"><div class="demo-box">Make yourself at home.<p>Try every control. All devices here are simulated.</p></div><div class="avatar"><b>G</b><span>Guest explorer<small>Your personal demo</small></span></div></div></aside><main class="main"><header class="topbar"><span>My home <span style="color:#b2bbb5;margin:0 12px">/</span> <b>${view}</b></span><div class="right"><span class="pill"><i class="dot"></i> Demo mode</span><span class="muted">Your home. Connected.</span></div></header><div class="content"><div class="heading"><div><h1>${view==='Overview'?'Welcome home.':view==='Energy'?'Small changes. Measurable impact.':'Thoughtfully connected.'}</h1><p class="muted">${view==='Overview'?'Your space, just the way you like it.':view==='Energy'?'Explore the energy behind your everyday comfort.':'Explore the Fosslink system, from control to comfort.'}</p></div><div class="actions">${view==='Overview'?`<button data-theme aria-label="Toggle light or dark theme">${icon('sun')}</button><button data-customize>${icon('settings')} Customize</button><button class="primary" data-add>${icon('plus')} Add device</button>`:''}</div></div>${view==='Overview'?dashboard():view==='Energy'?energyView():systemView()}<p class="footnote">Fosslink interactive demo · Simulated devices and estimates. Changes reset on reload; layout preferences stay in this browser.${view==='Energy'?' Savings compare current settings with all listed devices at rated power for the same 8-hour daily duration.':''}</p></div></main></div>`}
function log(s){events.unshift(s);events=events.slice(0,3)}function updateStats(){const vals={'active-count':devices.filter(d=>d.on).length+' <small>/ '+devices.length+' devices</small>','power':`${(total()/1000).toFixed(2)} <small>kW</small>`,'daily':`${(total()*8/1000).toFixed(2)} <small>kWh / 8 hours</small>`,'cost':`₹${(total()*8/1000*8).toFixed(2)}`,'saving':`Your settings use ${Math.round((1-total()/full())*100)}% less power than all devices at full output.`};Object.entries(vals).forEach(([id,s])=>{let el=document.getElementById(id);if(el)el.innerHTML=s})}
function openModal(html){detailId=null;modal.className='';modal.innerHTML=html;modal.showModal()}function closeButtons(){return '<div class="actions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save</button></div>'}
app.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let x=b.dataset;
if('theme'in x){document.body.classList.toggle('light-theme');try{localStorage.setItem('fosslink-theme',document.body.classList.contains('light-theme')?'light':'dark')}catch{}}else if(x.nav){view=x.nav;render();window.scrollTo(0,0)}
else if(x.room){room=x.room;render()}
else if(x.toggle){let d=devices.find(d=>d.id==x.toggle);d.on=!d.on;scene='';log(`${d.name} turned ${d.on?'on':'off'}`);render()}
else if(x.master){let on=!devices.some(d=>d.on);devices.forEach(d=>d.on=on);scene='';log(`All devices turned ${on?'on':'off'}`);render();toast(`All devices are ${on?'on':'off'}`)}
else if(x.scene){scene=x.scene;devices.forEach(d=>{d.on=scene==='Good morning'||scene==='Movie time'&&d.room==='Living room';if(d.type==='light'){d.value=scene==='Movie time'?20:80;d.temp=scene==='Movie time'?2700:4200}else if(d.type==='fan')d.value=40});log(`${scene} scene activated`);render();toast(`${scene} applied to your home`)}
else if(x.color){devices.find(d=>d.id==x.id).color=x.color;render()}
else if(x.step){let d=devices.find(d=>d.id==x.id);d[x.key]=Math.max(+x.min,Math.min(+x.max,d[x.key]+ +x.step));if(d.type!=='climate'&&x.key==='value')d.on=d.value>0;scene='';render();app.querySelector('[data-id="'+d.id+'"][data-key="'+x.key+'"][data-step="'+x.step+'"]')?.focus()}

else if(x.period){period=x.period;render()}
else if('customize'in x)openModal(`<form id="preferences"><h2>Make it feel like your home</h2><label for="control">Device controls</label><select id="control" name="control"><option value="slider" ${prefs.control==='slider'?'selected':''}>Sliders — smooth adjustments</option><option value="step" ${prefs.control==='step'?'selected':''}>Step buttons — precise adjustments</option></select><label><input name="compact" type="checkbox" ${prefs.compact?'checked':''}> Compact device cards</label><p class="footnote">Saved only in this browser.</p>${closeButtons()}</form>`);
else if('add'in x)openModal(`<form id="add-device"><h2>Add a demo device</h2><label for="name">Device name</label><input id="name" name="name" required maxlength="45" placeholder="e.g. Reading light"><label for="type">Device type</label><select id="type" name="type"><option value="light">Color light / LED strip</option><option value="fan">Fan</option><option value="climate">Thermostat</option><option value="tablet">Tablet display</option><option value="plug">Smart plug</option></select><label for="room">Room</label><select id="room" name="room">${['Living room','Bedroom','Kitchen','Office'].map(r=>`<option>${r}</option>`).join('')}</select>${closeButtons()}</form>`);
else if(x.timer){let d=devices.find(d=>d.id==x.timer);openModal(`<form id="timer" data-id="${d.id}"><h2>${esc(d.name)} timer</h2><p>Turn this device off after a duration. Keep this demo tab open for the timer to run.</p><label for="minutes">Duration in minutes</label><input id="minutes" name="minutes" type="number" min="1" max="1440" value="30" required>${d.until?'<button type="button" data-cancel-timer="'+d.id+'">Remove existing timer</button>':''}${closeButtons()}</form>`)}});
app.addEventListener('input',e=>{const x=e.target.dataset;if(!x.id||!x.key)return;const d=devices.find(d=>d.id==x.id);d[x.key]=Number(e.target.value);if(x.key==='value'&&d.type!=='climate')d.on=d.value>0;scene='';e.target.style.setProperty('--position',((d[x.key]-Number(e.target.min))/(Number(e.target.max)-Number(e.target.min))*100)+'%');document.getElementById('out-'+d.id+'-'+x.key).textContent=d[x.key]+x.unit;document.getElementById('watts-'+d.id).textContent=Math.round(watts(d))+' W';const card=e.target.closest('.device');card.classList.toggle('off',!d.on);card.querySelector('.device-info span').textContent=deviceState(d);card.querySelectorAll('[role=switch]').forEach(b=>b.setAttribute('aria-checked',d.on));updateStats()});
app.addEventListener('change',e=>{if(!e.target.matches('.tile-slider'))return;const id=e.target.dataset.id,key=e.target.dataset.key;render();app.querySelector('input[data-id="'+id+'"][data-key="'+key+'"]')?.focus()});
modal.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if('close'in b.dataset)modal.close();if(b.dataset.cancelTimer){let d=devices.find(d=>d.id==b.dataset.cancelTimer);d.until=null;modal.close();render();toast('Timer removed')}});
modal.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f);if(f.id==='preferences'){prefs={control:data.get('control'),compact:data.has('compact')};try{localStorage.setItem('fosslink-preferences',JSON.stringify(prefs))}catch{}toast('Your layout is ready')}
if(f.id==='add-device'){let name=data.get('name').trim();if(!name){document.getElementById('name').setCustomValidity('Enter a device name');document.getElementById('name').reportValidity();return}let type=data.get('type');devices.push({id:Date.now(),name,room:data.get('room'),type,on:false,value:type==='climate'?23:50,temp:3200,color:'#a1c985',watts:{light:24,fan:70,climate:1200,tablet:15,plug:850}[type]});room=data.get('room');log(`${name} added`);toast('Demo device added')}
if(f.id==='timer'){let d=devices.find(d=>d.id==f.dataset.id);d.until=Date.now()+Number(data.get('minutes'))*60000;toast(`Timer set for ${data.get('minutes')} minutes`)}modal.close();render()});
setInterval(()=>{let expired=devices.filter(d=>d.until&&Date.now()>=d.until);if(expired.length){expired.forEach(d=>{d.on=false;d.until=null;log(`${d.name} timer completed`)});render();toast('Timer completed — device turned off')}},1000);
try{if(localStorage.getItem('fosslink-theme')==='light')document.body.classList.add('light-theme')}catch{}
render();
